/** URLs generated by sharing/email widgets are actions, not indexable content pages. */
export function isNonContentUtilityUrl(value: string): boolean {
  try {
    const url = new URL(value);
    const path = url.pathname.replace(/\/+$/, '').toLowerCase();
    if (path === '/cdn-cgi/l/email-protection' || path === '/email-protection') return true;
    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    if (
      (host === 'facebook.com' && path === '/sharer/sharer.php') ||
      ((host === 'twitter.com' || host === 'x.com') && path.startsWith('/intent/')) ||
      (host === 'linkedin.com' && path === '/sharing/share-offsite') ||
      (host === 'api.whatsapp.com' && path === '/send') ||
      (host === 'wa.me' && path === '/')
    )
      return true;
    // WordPress/Jetpack share buttons use ?share=service or ?shared=email.
    if (url.searchParams.has('share') || url.searchParams.has('shared')) return true;
    // WordPress print/email action links (do not exclude normal ?email= form links).
    if (url.searchParams.has('print')) return true;
    return false;
  } catch {
    return false;
  }
}
